/**
 * Default categories for new families
 * Specification: #{#exp3a} Requirement 3
 *
 * Updated with user's custom category list
 * Families can replace, delete, or ignore these categories as needed
 */
const DEFAULT_CATEGORIES: DefaultCategory[] = [
	{ name: 'Alcohol', color: '#DC2626' },
	{ name: 'Kids - Allowance', color: '#F97316' },
	{ name: 'Kids - Activities', color: '#FB923C' },
