	{ name: 'University expenses', color: '#C026D3' },
	{ name: 'Utilities', color: '#6366F1' }
];

/**
 * CategoryService Class
 * Handles all category-related operations
 */
export class CategoryService {
	private supabase: SupabaseClient;

	constructor(supabase: SupabaseClient) {
		this.supabase = supabase;
	}

	/**
	 * Get list of default categories
	 * Specification: #{#exp3a} Requirement 3
	 */
	getDefaultCategoryList(): DefaultCategory[] {
		return DEFAULT_CATEGORIES;
	}

	/**
	 * Get all categories for a family
	 *
	 * @param familyId - Family ID to filter categories
	 * @returns Array of categories ordered by name
	 *
	 * Specification: #{#exp3a} Requirement 1
	 */
	async getFamilyCategories(familyId: string): Promise<Category[]> {
		// Requirement: Family ID validation
		if (!familyId) {
			throw new Error('Family ID is required');
		}

		// Query categories filtered by family_id
		// RLS policies ensure user is an active member of this family
		const { data, error } = await this.supabase
			.from('categories')
			.select('*')
			.eq('family_id', familyId)
			.order('name', { ascending: true });

		if (error) {
			throw new Error(error.message);
		}

		return data || [];
	}

	/**
	 * DEPRECATED: Use getFamilyCategories instead
	 * @deprecated This method is maintained for backward compatibility
	 */
	async getUserCategories(userId: string): Promise<Category[]> {
		console.warn('getUserCategories is deprecated. Use getFamilyCategories instead.');

		// Get user's default family and fetch categories for that family
		const { data: familyMember, error: fmError } = await this.supabase
			.from('family_members')
			.select('family_id')
			.eq('user_id', userId)
			.eq('is_default', true)
			.eq('status', 'active')
			.single();

		if (fmError || !familyMember) {
			throw new Error('Could not find default family for user');
		}

