/**
 * Spending Report comparison (pure)
 *
 * Attaches a comparison-period total (`priorTotal`) to every row of a
 * SpendingReport so the table can render a Change column and the chart can draw
 * a side-by-side prior bar.
 *
 * Two comparison periods are offered:
 * - **Prior year** — the selected period shifted back 12 months. Controls for
 *   seasonality and is what keeps this a year-over-year report.
 * - **Previous period** — shifted back by the period's own length. Useful on a
 *   short period, seasonally meaningless, so it is offered *alongside* rather
 *   than instead. At 12 months the two coincide, and only one is offered.
 *
 * Either way the parity rule holds: the comparison is summed over the **same
 * number of whole months the current report actually shows**, so a part-elapsed
 * period can never lose by construction.
 *
 * No I/O — a plain transform, unit-tested like `buildSpendingReport`.
 *
 * Design: docs/plans/2026-07-09-spending-report-design.md
 */

import type { SpendingReport, ReportRow, GroupSection } from './spendingReport';
import { formatPeriod, periodLength, shiftPeriod, type Period } from './spendingPeriod';

// Kept in lock-step with `spendingReport.ts` (the "(No category)" catch-all row).
const NO_CATEGORY_ROW = '(No category)';

/** Which window the current period is measured against. */
export type CompareMode = 'priorYear' | 'priorPeriod';

/** The window a mode compares against. */
export function comparisonPeriod(period: Period, mode: CompareMode): Period {
	return shiftPeriod(period, mode === 'priorYear' ? -12 : -periodLength(period));
}

/**
 * The comparison modes worth offering for a period, in menu order.
 *
 * A 12-month period shifts back a year either way, so the two modes name the
 * same window and only one is listed.
 */
export function comparisonModes(period: Period): CompareMode[] {
	return periodLength(period) === 12 ? ['priorYear'] : ['priorYear', 'priorPeriod'];
}

/** Menu label for a mode, naming the window it actually compares against. */
export function comparisonLabel(period: Period, mode: CompareMode): string {
	return formatPeriod(comparisonPeriod(period, mode));
}

/** Sum a comparison row's month cells over the first `window` months. */
function priorWindowSum(row: ReportRow, window: number): number {
	let total = 0;
	const upto = Math.min(window, row.cells.length);
	for (let i = 0; i < upto; i++) total += row.cells[i].amount;
	return total;
}

/** Lookups into the comparison report, keyed by the ids the current report carries. */
interface PriorIndex {
	byCategoryId: Map<string, ReportRow>;
	noCategoryRow: ReportRow | null;
	groupSubtotalById: Map<string, ReportRow>;
	importanceSubtotalById: Map<string, ReportRow>;
	uncategorizedSubtotal: ReportRow | null;
	grandTotal: ReportRow;
}

function indexPrior(prior: SpendingReport): PriorIndex {
	const byCategoryId = new Map<string, ReportRow>();
	const groupSubtotalById = new Map<string, ReportRow>();
	const importanceSubtotalById = new Map<string, ReportRow>();

	const indexRows = (section: GroupSection) => {
		for (const row of section.rows) {
			if (row.categoryId) byCategoryId.set(row.categoryId, row);
		}
	};

	for (const imp of prior.importances) {
		importanceSubtotalById.set(imp.id, imp.subtotal);
		for (const group of imp.groups) {
			if (group.id) groupSubtotalById.set(group.id, group.subtotal);
			indexRows(group);
		}
	}

	let noCategoryRow: ReportRow | null = null;
	if (prior.uncategorized) {
		indexRows(prior.uncategorized);
		noCategoryRow =
			prior.uncategorized.rows.find((r) => r.name === NO_CATEGORY_ROW && !r.categoryId) ?? null;
	}

	return {
		byCategoryId,
		noCategoryRow,
		groupSubtotalById,
		importanceSubtotalById,
		uncategorizedSubtotal: prior.uncategorized ? prior.uncategorized.subtotal : null,
		grandTotal: prior.grandTotal
	};
}

/** Does the comparison period have any activity to compare against? (Gates the menu.) */
export function hasPriorData(prior: SpendingReport): boolean {
	return prior.grandTotal.total.count > 0;
}

/**
 * Return a copy of `report` with `priorTotal` on every row, summed from the same
 * number of months of `priorReport`.
 *
 * Rows are matched by id (category / group / importance), the "(No category)"
 * row by name; anything with no match in the comparison period gets `0` (it
 * existed this period, spent nothing last). A row that spent in the comparison
 * period but not this one has no row here to annotate — see the design's
 * "disappeared spend" limitation.
 *
 * Non-mutating: the page swaps comparison modes by re-deriving from the same
 * base report, so annotating in place would leave a stale `priorTotal` behind
 * when the comparison is switched off.
 */
export function withPriorPeriod(
	report: SpendingReport,
	priorReport: SpendingReport
): SpendingReport {
	const window = report.months.length;
	const idx = indexPrior(priorReport);

	const sumFor = (prior: ReportRow | null | undefined): number =>
		prior ? priorWindowSum(prior, window) : 0;

	const rowPrior = (row: ReportRow): number => {
		if (row.categoryId) return sumFor(idx.byCategoryId.get(row.categoryId));
		if (row.name === NO_CATEGORY_ROW) return sumFor(idx.noCategoryRow);
		return 0;
	};

	const annotate = (row: ReportRow, priorTotal: number): ReportRow => ({ ...row, priorTotal });
	const annotateSection = (section: GroupSection, subtotalPrior: number): GroupSection => ({
		...section,
		rows: section.rows.map((row) => annotate(row, rowPrior(row))),
		subtotal: annotate(section.subtotal, subtotalPrior)
	});

	return {
		...report,
		importances: report.importances.map((imp) => ({
			...imp,
			groups: imp.groups.map((group) =>
				annotateSection(group, group.id ? sumFor(idx.groupSubtotalById.get(group.id)) : 0)
			),
			subtotal: annotate(imp.subtotal, sumFor(idx.importanceSubtotalById.get(imp.id)))
		})),
		uncategorized: report.uncategorized
			? annotateSection(report.uncategorized, sumFor(idx.uncategorizedSubtotal))
			: null,
		grandTotal: annotate(report.grandTotal, priorWindowSum(idx.grandTotal, window))
	};
}

export interface SpendingChange {
	/** current − prior (positive = spent more). */
	delta: number;
	/** Percent change vs prior; null when prior is 0 (undefined growth → "new"). */
	pct: number | null;
	direction: 'up' | 'down' | 'flat';
}

/** Compute the change from a comparison-period total to the current total. */
export function spendingChange(current: number, prior: number): SpendingChange {
	const delta = current - prior;
	// Divide by |prior| so a negative prior (net refund) doesn't flip the sign.
	const pct = prior !== 0 ? (delta / Math.abs(prior)) * 100 : null;
	const direction = delta > 0 ? 'up' : delta < 0 ? 'down' : 'flat';
	return { delta, pct, direction };
}

