import { describe, it, expect } from 'vitest';
import { buildSpendingReport, type SpendingExpense, type SpendingCategory } from './spendingReport';
import type { ImportanceArea, CategoryGroup } from '$lib/types/Hierarchy';
import type { Period, YearMonth } from './spendingPeriod';
import {
	comparisonLabel,
	comparisonModes,
	comparisonPeriod,
	hasPriorData,
	spendingChange,
	withPriorPeriod
} from './spendingComparison';

// --- fixtures (shared shape with spendingReport.spec) -----------------------

const importanceAreas: ImportanceArea[] = [
	{ id: 'imp-ess', name: 'Essential', sort_order: 1 },
	{ id: 'imp-pri', name: 'Priorities', sort_order: 2 },
	{ id: 'imp-oth', name: 'Other', sort_order: 3 }
];

const groups: CategoryGroup[] = [
	{ id: 'grp-everyday', name: 'Everyday', importance_area_id: 'imp-ess' },
	{ id: 'grp-home', name: 'Home', importance_area_id: 'imp-ess' },
	{ id: 'grp-kids', name: 'Kids', importance_area_id: 'imp-pri' }
];

const categories: SpendingCategory[] = [
	{ id: 'cat-groceries', name: 'Groceries', group_id: 'grp-everyday' },
	{ id: 'cat-clothes', name: 'Clothes', group_id: 'grp-everyday' },
	{ id: 'cat-utilities', name: 'Utilities', group_id: 'grp-home' },
	{ id: 'cat-allowance', name: 'Allowance', group_id: 'grp-kids' },
	{ id: 'cat-orphan', name: 'Orphan', group_id: null }
];

/** The whole calendar year `y`, the report's default period shape. */
function yearPeriod(y: number): Period {
	return { from: { year: y, month: 1 }, to: { year: y, month: 12 } };
}

function expense(overrides: Partial<SpendingExpense>): SpendingExpense {
	return {
		total_amount: 100,
		transaction_date: '2026-01-15',
		category_id: 'cat-groceries',
		exchange_rate_to_cad: null,
		...overrides
	};
}

function reportFor(expenses: SpendingExpense[], period: Period, today?: YearMonth) {
	return buildSpendingReport(
		expenses,
		categories,
		groups,
		importanceAreas,
		period,
		today ?? period.from
	);
}

/** Build current + prior-year reports and attach the comparison in one step. */
function compared(current: SpendingExpense[], prior: SpendingExpense[], year = 2026) {
	const currentReport = reportFor(current, yearPeriod(year));
	const priorReport = reportFor(prior, yearPeriod(year - 1), { year, month: 12 });
	return withPriorPeriod(currentReport, priorReport);
}

function findRow(
	r: ReturnType<typeof reportFor>,
	importance: string,
	group: string,
	category: string
) {
	const imp = r.importances.find((i) => i.name === importance);
	const grp = imp?.groups.find((g) => g.name === group);
	return grp?.rows.find((row) => row.name === category);
}

// --- which window a mode compares against -----------------------------------

describe('comparisonPeriod', () => {
	it('shifts back exactly a year for the prior-year mode, whatever the length', () => {
		const period: Period = { from: { year: 2026, month: 4 }, to: { year: 2026, month: 6 } };
		expect(comparisonPeriod(period, 'priorYear')).toEqual({
			from: { year: 2025, month: 4 },
			to: { year: 2025, month: 6 }
		});
	});

	it('shifts back by the period’s own length for the previous-period mode', () => {
		const period: Period = { from: { year: 2026, month: 4 }, to: { year: 2026, month: 6 } };
		expect(comparisonPeriod(period, 'priorPeriod')).toEqual({
			from: { year: 2026, month: 1 },
			to: { year: 2026, month: 3 }
		});
	});

	it('the two modes coincide for a 12-month period', () => {
		const period = yearPeriod(2026);
		expect(comparisonPeriod(period, 'priorPeriod')).toEqual(comparisonPeriod(period, 'priorYear'));
	});
});

describe('comparisonModes', () => {
	it('offers only the prior year for a 12-month period (the modes coincide)', () => {
		expect(comparisonModes(yearPeriod(2026))).toEqual(['priorYear']);
		expect(
			comparisonModes({ from: { year: 2025, month: 7 }, to: { year: 2026, month: 6 } })
		).toEqual(['priorYear']);
	});

	it('offers both for a shorter period', () => {
		expect(
			comparisonModes({ from: { year: 2026, month: 4 }, to: { year: 2026, month: 6 } })
		).toEqual(['priorYear', 'priorPeriod']);
	});
});

describe('comparisonLabel', () => {
	it('names the window a mode actually compares against', () => {
		const period: Period = { from: { year: 2026, month: 4 }, to: { year: 2026, month: 6 } };
		expect(comparisonLabel(period, 'priorYear')).toBe('Apr–Jun 2025');
		expect(comparisonLabel(period, 'priorPeriod')).toBe('Jan–Mar 2026');
	});
});

// --- withPriorPeriod --------------------------------------------------------

describe('withPriorPeriod', () => {
	it('attaches the prior-year total to a matching category, group, importance and grand total', () => {
		const r = compared(
			[expense({ transaction_date: '2026-01-10', total_amount: 100 })],
			[expense({ transaction_date: '2025-01-10', total_amount: 80 })]
		);

